<?php $me=current_user(); ?>
<section class="page-heading"><p class="eyebrow">YOUR ACCOUNT</p><h1>Profile.</h1><p>Keep your details current. Your phone number is only shared directly when you choose.</p></section>
<div class="profile-layout"><div class="profile-stack"><form method="post" enctype="multipart/form-data" class="form-panel profile-form"><h2>Personal details</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="profile"><input type="hidden" name="return_page" value="profile"><div class="profile-identity"><?php if(!empty($me['profile_photo'])): ?><img class="avatar avatar-large profile-photo" src="<?= e($me['profile_photo']) ?>" alt="Profile photo"><?php else: ?><span class="avatar avatar-large"><?= e(strtoupper(substr($me['name'],0,1))) ?></span><?php endif; ?><span><strong><?= e($me['name']) ?></strong><small><?= e(ucfirst($me['role'])) ?> · <span class="verify-tag">● <?= !empty($me['is_verified'])?'Verified':'Not verified' ?></span></small></span></div><div class="mb-3"><label class="form-label" for="name">Name</label><input class="form-control" id="name" name="name" value="<?= e($me['name']) ?>" maxlength="100" required></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" value="<?= e($me['email']) ?>" disabled><div class="form-text">Email changes are not available in this demo.</div></div><div class="mb-3"><label class="form-label" for="phone">Phone</label><input class="form-control" id="phone" name="phone" value="<?= e($me['phone']??'') ?>" maxlength="30" type="tel"></div><div class="mb-4"><label class="form-label" for="profile_photo">Profile photo <span class="muted">(JPEG, PNG or WebP; max 2 MB)</span></label><input class="form-control" id="profile_photo" name="profile_photo" type="file" accept="image/jpeg,image/png,image/webp"></div><button class="btn btn-primary">Save profile</button></form><form method="post" class="form-panel password-form"><h2>Change password</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="change_password"><input type="hidden" name="return_page" value="profile"><div class="mb-3"><label class="form-label" for="current_password">Current password</label><input class="form-control" id="current_password" name="current_password" type="password" autocomplete="current-password" required></div><div class="mb-3"><label class="form-label" for="new_password">New password</label><input class="form-control" id="new_password" name="new_password" type="password" minlength="10" autocomplete="new-password" required><div class="form-text">At least 10 characters.</div></div><button class="btn btn-outline-dark">Update password</button></form></div><div class="profile-reviews"><div class="section-head"><h2>Reviews received</h2><span><?= count($data['reviews']) ?> total</span></div><?php if(!$data['reviews']): ?><p class="muted">Reviews from completed journeys will appear here.</p><?php endif; ?><?php foreach($data['reviews'] as $review): ?><article class="review-item"><div><strong><?= e($review['reviewer_name']) ?></strong><span class="review-stars"><?= str_repeat('★',(int)$review['rating']) ?><?= str_repeat('☆',5-(int)$review['rating']) ?></span></div><small><?= e($review['origin']) ?> → <?= e($review['destination']) ?> · <?= e(date('M j, Y',strtotime($review['created_at']))) ?></small><p><?= e($review['comment']) ?></p><?php if(!$review['is_reported'] && (int)$review['reviewed_user_id']===(int)$me['id']): ?><form method="post" class="report-review" data-confirm="Report this review to MAPIDO administrators?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="report_review"><input type="hidden" name="return_page" value="profile"><input type="hidden" name="review_id" value="<?= (int)$review['id'] ?>"><button class="btn btn-link btn-sm">Report review</button></form><?php elseif($review['is_reported']): ?><small class="muted">Reported for review</small><?php endif; ?></article><?php endforeach; ?></div></div>